  1→use crate::config::Config;
  2→use crate::discovery::ModelFile;
  3→use crate::selector::{SelectionMethod, Selector};
  4→use anyhow::{anyhow, Result};
  5→use smelt_core::SourcesConfig;
  6→use std::collections::{HashMap, HashSet, VecDeque};
  7→use thiserror::Error;
  8→
  9→#[derive(Debug, Error)]
 10→pub enum GraphError {
 11→    #[error("Dependency resolution failed:\n  {message}")]
 12→    DependencyError { message: String },
 13→
 14→    #[error("Circular dependency detected involving models: {models}")]
 15→    CircularDependency { models: String },
 16→}
 17→
 18→pub struct DependencyGraph {
 19→    /// model_name -> dependencies (model names it references)
 20→    dependencies: HashMap<String, Vec<String>>,
 21→    /// model_name -> ModelFile
 22→    models: HashMap<String, ModelFile>,
 23→    /// External sources (from sources.yml)
 24→    sources: HashSet<String>,
 25→}
 26→
 27→impl DependencyGraph {
 28→    pub fn build(models: Vec<ModelFile>, sources: Option<&SourcesConfig>) -> Result<Self> {
 29→        let mut dependencies = HashMap::new();
 30→        let mut models_map: HashMap<String, ModelFile> = HashMap::new();
 31→
 32→        // Build source set (schema.table format)
 33→        let mut source_set = HashSet::new();
 34→        if let Some(sources) = sources {
 35→            for source in &sources.sources {
 36→                for table in &source.tables {
 37→                    source_set.insert(format!("{}.{}", source.name, table.name));
 38→                }
 39→            }
 40→        }
 41→
 42→        // Build dependency map
 43→        for model in models {
 44→            let deps: Vec<String> = model.refs.iter().map(|r| r.model_name.clone()).collect();
 45→
 46→            if let Some(existing) = models_map.get(&model.name) {
 47→                eprintln!(
 48→                    "Warning: Duplicate model name '{}'. Model at {} overwrites model at {}.",
 49→                    model.name,
 50→                    model.path.display(),
 51→                    existing.path.display()
 52→                );
 53→            }
 54→            dependencies.insert(model.name.clone(), deps);
 55→            models_map.insert(model.name.clone(), model);
 56→        }
 57→
 58→        Ok(Self {
 59→            dependencies,
 60→            models: models_map,
 61→            sources: source_set,
 62→        })
 63→    }
 64→
 65→    /// Validate all references exist (either as models or sources)
 66→    pub fn validate(&self) -> Result<()> {
 67→        let mut errors = Vec::new();
 68→
 69→        for (model_name, deps) in &self.dependencies {
 70→            for dep in deps {
 71→                // Check if dependency exists as a model or source
 72→                if !self.models.contains_key(dep) && !self.is_source(dep) {
 73→                    errors.push(format!(
 74→                        "Model '{}' references undefined model/source '{}'",
 75→                        model_name, dep
 76→                    ));
 77→                }
 78→            }
 79→        }
 80→
 81→        if !errors.is_empty() {
 82→            return Err(GraphError::DependencyError {
 83→                message: errors.join("\n  "),
 84→            }
 85→            .into());
 86→        }
 87→
 88→        Ok(())
 89→    }
 90→
 91→    fn is_source(&self, name: &str) -> bool {
 92→        // Check both plain name and schema.table format
 93→        self.sources.contains(name)
 94→            || self
 95→                .sources
 96→                .iter()
 97→                .any(|s| s.ends_with(&format!(".{}", name)))
 98→    }
 99→
100→    /// Topological sort to determine execution order using Kahn's algorithm
101→    pub fn execution_order(&self) -> Result<Vec<String>> {
102→        let mut in_degree: HashMap<String, usize> = HashMap::new();
103→        let mut dependents: HashMap<String, Vec<String>> = HashMap::new();
104→
105→        // Initialize in-degree for all models
106→        for model_name in self.models.keys() {
107→            in_degree.insert(model_name.clone(), 0);
108→            dependents.insert(model_name.clone(), Vec::new());
109→        }
110→
111→        // Count incoming edges (dependencies)
112→        for (model_name, deps) in &self.dependencies {
113→            for dep in deps {
114→                // Only count model dependencies (skip sources)
115→                if self.models.contains_key(dep) {
116→                    *in_degree.get_mut(model_name).unwrap() += 1;
117→                    dependents.get_mut(dep).unwrap().push(model_name.clone());
118→                }
119→            }
120→        }
121→
122→        // Kahn's algorithm for topological sort
123→        let mut queue: VecDeque<String> = in_degree
124→            .iter()
125→            .filter(|(_, &degree)| degree == 0)
126→            .map(|(name, _)| name.clone())
127→            .collect();
128→
129→        let mut order = Vec::new();
130→
131→        while let Some(model_name) = queue.pop_front() {
132→            order.push(model_name.clone());
133→
134→            // Reduce in-degree for dependents
135→            if let Some(deps) = dependents.get(&model_name) {
136→                for dependent in deps {
137→                    let degree = in_degree.get_mut(dependent).unwrap();
138→                    *degree -= 1;
139→
140→                    if *degree == 0 {
141→                        queue.push_back(dependent.clone());
142→                    }
143→                }
144→            }
145→        }
146→
147→        // Check for cycles
148→        if order.len() != self.models.len() {
149→            let remaining: Vec<_> = in_degree
150→                .iter()
151→                .filter(|(_, &degree)| degree > 0)
152→                .map(|(name, _)| name.as_str())
153→                .collect();
154→
155→            return Err(GraphError::CircularDependency {
156→                models: remaining.join(", "),
157→            }
158→            .into());
159→        }
160→
161→        Ok(order)
162→    }
163→
164→    /// Select models matching the given selectors, with optional upstream/downstream expansion.
165→    ///
166→    /// Returns the set of selected model names. The result is the union of all selectors.
167→    pub fn select_models(
168→        &self,
169→        selectors: &[Selector],
170→        config: &Config,
171→    ) -> Result<HashSet<String>> {
172→        let mut selected = HashSet::new();
173→        let dependents = self.build_dependents_map();
174→
175→        for selector in selectors {
176→            // Find directly matching models
177→            let direct_matches: Vec<String> = match &selector.method {
178→                SelectionMethod::ModelName(name) => {
179→                    if self.models.contains_key(name) {
180→                        vec![name.clone()]
181→                    } else {
182→                        return Err(anyhow!("Model '{}' not found", name));
183→                    }
184→                }
185→                SelectionMethod::Tag(tag) => self
186→                    .models
187→                    .iter()
188→                    .filter(|(name, model)| {
189→                        let tags =
190→                            config.get_tags(name, model.metadata.as_ref().map(|b| b.as_ref()));
191→                        tags.contains(tag)
192→                    })
193→                    .map(|(name, _)| name.clone())
194→                    .collect(),
195→            };
196→
197→            for model_name in &direct_matches {
198→                selected.insert(model_name.clone());
199→            }
200→
201→            // Expand upstream
202→            if selector.include_upstream {
203→                for model_name in &direct_matches {
204→                    self.collect_upstream(model_name, &mut selected);
205→                }
206→            }
207→
208→            // Expand downstream
209→            if selector.include_downstream {
210→                for model_name in &direct_matches {
211→                    self.collect_downstream(model_name, &dependents, &mut selected);
212→                }
213→            }
214→        }
215→
216→        Ok(selected)
217→    }
218→
219→    /// Collect all upstream dependencies recursively.
220→    fn collect_upstream(&self, model_name: &str, result: &mut HashSet<String>) {
221→        if let Some(deps) = self.dependencies.get(model_name) {
222→            for dep in deps {
223→                if self.models.contains_key(dep) && result.insert(dep.clone()) {
224→                    self.collect_upstream(dep, result);
225→                }
226→            }
227→        }
228→    }
229→
230→    /// Build a reverse map: model_name -> models that depend on it.
231→    fn build_dependents_map(&self) -> HashMap<String, Vec<String>> {
232→        let mut dependents: HashMap<String, Vec<String>> = HashMap::new();
233→        for (model_name, deps) in &self.dependencies {
234→            for dep in deps {
235→                if self.models.contains_key(dep) {
236→                    dependents
237→                        .entry(dep.clone())
238→                        .or_default()
239→                        .push(model_name.clone());
240→                }
241→            }
242→        }
243→        dependents
244→    }
245→
246→    /// Collect all downstream dependents recursively.
247→    fn collect_downstream(
248→        &self,
249→        model_name: &str,
250→        dependents: &HashMap<String, Vec<String>>,
251→        result: &mut HashSet<String>,
252→    ) {
253→        if let Some(deps) = dependents.get(model_name) {
254→            for dep in deps {
255→                if result.insert(dep.clone()) {
256→                    self.collect_downstream(dep, dependents, result);
257→                }
258→            }
259→        }
260→    }
261→
262→    /// Filter execution order to only include selected models.
263→    pub fn filtered_execution_order(&self, selected: &HashSet<String>) -> Result<Vec<String>> {
264→        let full_order = self.execution_order()?;
265→        Ok(full_order
266→            .into_iter()
267→            .filter(|name| selected.contains(name))
268→            .collect())
269→    }
270→
271→    pub fn get_model(&self, name: &str) -> Result<&ModelFile> {
272→        self.models
273→            .get(name)
274→            .ok_or_else(|| anyhow!("Model not found: {}", name))
275→    }
276→
277→    pub fn models(&self) -> &HashMap<String, ModelFile> {
278→        &self.models
279→    }
280→
281→    /// Get the upstream dependencies for a model (model names it references).
282→    pub fn get_upstream(&self, model_name: &str) -> Vec<String> {
283→        self.dependencies
284→            .get(model_name)
285→            .cloned()
286→            .unwrap_or_default()
287→            .into_iter()
288→            .filter(|dep| self.models.contains_key(dep))
289→            .collect()
290→    }
291→
292→    /// Collect all upstream dependencies recursively (public wrapper).
293→    pub fn all_upstream(&self, model_name: &str) -> HashSet<String> {
294→        let mut result = HashSet::new();
295→        self.collect_upstream(model_name, &mut result);
296→        result
297→    }
298→}
